/**
 * A private room's ticket, from the host that served the page: loaded only when a page names one, so a public
 * world's page carries none of it.
 */

/**
 * Asks the page's host (`room-ticket`) for a ticket to its world's room, with the page's own cookies and never from
 * a cache: a ticket lapses, so each join asks again. Null when the host gives none (signed out, or not on the list);
 * a network failure throws, so the caller treats it as a blip and retries.
 */
export async function roomTicket(path: string, fetchImpl: (url: string, init?: RequestInit) => Promise<Response>): Promise<string | null> {
  const res = await fetchImpl(path, { credentials: 'same-origin', cache: 'no-store' });
  if (!res.ok) return null;
  const body = (await res.json()) as { ticket?: unknown };
  return typeof body.ticket === 'string' && body.ticket ? body.ticket : null;
}
